    const questionBank = [{"id":"s1","dim":"stress","text":{"fr":"J’ai l’impression d’avoir l’esprit surchargé.","en":"I feel mentally overloaded.","ar":"أشعر بأن ذهني مثقل.","darija":"كنحس بحالي راسي عامر ومجهد."}},{"id":"s2","dim":"stress","text":{"fr":"J’ai du mal à me détendre.","en":"I find it hard to relax.","ar":"أجد صعوبة في الاسترخاء.","darija":"كتصعاب عليا نرتاح."}},{"id":"s3","dim":"stress","text":{"fr":"Je reste tendu·e, notamment dans les épaules ou la mâchoire.","en":"My shoulders, jaw, or other muscles often feel tense.","ar":"أشعر بتوتر مستمر في جسدي، خاصة في الكتفين أو الفك.","darija":"كيبقى جسمي مشدود، خصوصا فالكتاف ولا الفك."}},{"id":"s4","dim":"stress","text":{"fr":"La pression me rend plus irritable.","en":"I feel more irritable when under pressure.","ar":"يجعلني الضغط سريع الانفعال.","darija":"الضغط كيخليني نتعصب بسهولة."}},{"id":"s5","dim":"stress","text":{"fr":"J’ai l’impression de devoir courir toute la journée.","en":"I feel as though I have to rush all day.","ar":"أشعر كأنني أركض طوال اليوم.","darija":"كنحس بحالي خاصني نبقى نجري النهار كامل."}},{"id":"s6","dim":"stress","text":{"fr":"Quand je suis stressé·e, j’ai parfois mal à la tête ou des tensions musculaires.","en":"When I feel stressed, I sometimes get headaches or muscle tension.","ar":"أصاب أحيانا بصداع أو شد عضلي عندما أكون تحت الضغط.","darija":"ملي كنكون مضغوط، كيجيّني مرات الصداع ولا كيتشد ليا جسمي."}},{"id":"a1","dim":"anxiety","text":{"fr":"Je m’inquiète souvent, même pour des choses que j’aimerais relativiser.","en":"I worry a lot, even when I would rather not.","ar":"أقلق كثيرا، حتى عندما لا أريد ذلك.","darija":"كنقلق بزاف حتى على حوايج ما بغيتش نقلق عليهم."}},{"id":"a2","dim":"anxiety","text":{"fr":"J’ai du mal à mettre mes inquiétudes de côté.","en":"I have trouble setting my worries aside.","ar":"يصعب علي أن أضع أفكاري المقلقة جانبا.","darija":"كتصعاب عليا نحيد الهموم من راسي."}},{"id":"a3","dim":"anxiety","text":{"fr":"Je me sens agité·e ou j’éprouve parfois une peur soudaine.","en":"I feel restless or sometimes suddenly afraid.","ar":"أشعر بالتململ أو بالخوف فجأة أحيانا.","darija":"كنحس براسي مقلق وما مرتاحش ولا كيجيّني الخوف فجأة."}},{"id":"a4","dim":"anxiety","text":{"fr":"Je réfléchis beaucoup à ce qui pourrait arriver.","en":"I spend a lot of time thinking about what might happen.","ar":"أفكر كثيرا فيما قد يحدث لاحقا.","darija":"كنبقى نفكر بزاف فشنو يقدر يوقع."}},{"id":"a5","dim":"anxiety","text":{"fr":"Quand je ressens du stress ou de l’anxiété, mon cœur s’accélère ou mon souffle se raccourcit.","en":"When I feel stressed or anxious, my heart races or my breathing feels short.","ar":"عندما أشعر بالضغط أو القلق، يتسارع نبض قلبي أو أشعر بقصر النفس.","darija":"ملي كنحس بالضغط ولا القلق، كيدق قلبي بسرعة ولا كيقصر ليا النفس."}},{"id":"a6","dim":"anxiety","text":{"fr":"Je crains souvent qu’un événement grave arrive.","en":"I often fear that something serious might happen.","ar":"أخشى كثيرا أن يحدث أمر خطير.","darija":"كنخاف بزاف يوقع شي أمر خطير."}},{"id":"d1","dim":"dépression","text":{"fr":"Je me sens triste ou vide.","en":"I feel sad or empty.","ar":"أشعر بالحزن أو بالفراغ.","darija":"كنحس بالحزن ولا بالفراغ."}},{"id":"d2","dim":"dépression","text":{"fr":"J’ai moins d’envie ou de plaisir dans les activités qui me plaisaient.","en":"I have less interest in, or enjoyment from, things I used to like.","ar":"قل اهتمامي أو استمتاعي بالأشياء التي كنت أحبها.","darija":"ما بقاتش كتعجبني بعض الحوايج ولا كتعطيني نفس المتعة بحال قبل."}},{"id":"d3","dim":"dépression","text":{"fr":"Je me sens fatigué·e, même sans raison évidente.","en":"I feel tired even when there is no clear reason.","ar":"أشعر بالتعب حتى دون سبب واضح.","darija":"كنحس بالعياء حتى إلا ما كانش سبب باين."}},{"id":"d4","dim":"dépression","text":{"fr":"Il m’arrive de me sentir sans valeur ou de m’en vouloir.","en":"At times I feel worthless or blame myself.","ar":"أشعر أحيانا أنني بلا قيمة أو ألوم نفسي.","darija":"مرات كنحس ما عندي قيمة ولا كنلوم راسي."}},{"id":"d5","dim":"dépression","text":{"fr":"J’ai tendance à m’isoler des autres.","en":"I tend to withdraw from other people.","ar":"أميل إلى الابتعاد عن الآخرين.","darija":"كنميل نبعد على الناس."}},{"id":"d6","dim":"dépression","text":{"fr":"J’ai du mal à envisager l’avenir avec optimisme.","en":"I find it hard to feel hopeful about the future.","ar":"يصعب علي أن أنظر إلى المستقبل بتفاؤل.","darija":"كتصعاب عليا نشوف المستقبل بتفاؤل."}},{"id":"sl1","dim":"sleep","text":{"fr":"J’ai du mal à m’endormir.","en":"I have difficulty falling asleep.","ar":"يصعب علي أن أغفو.","darija":"كتصعاب عليا ننعس."}},{"id":"sl2","dim":"sleep","text":{"fr":"Je me réveille plusieurs fois pendant la nuit.","en":"I wake up several times during the night.","ar":"أستيقظ عدة مرات أثناء الليل.","darija":"كنفيق كثر من مرة فالليل."}},{"id":"sl3","dim":"sleep","text":{"fr":"Au réveil, je ne me sens pas reposé·e.","en":"I do not feel rested when I wake up.","ar":"لا أشعر بالراحة عندما أستيقظ.","darija":"ملي كنفيق، ما كنحسش براسي مرتاح."}},{"id":"sl4","dim":"sleep","text":{"fr":"Mes difficultés de sommeil perturbent ma journée.","en":"Sleep difficulties make it harder to get through my day.","ar":"تؤثر صعوبات نومي في نشاطي خلال النهار.","darija":"مشاكل النعاس كتصعاب عليا ندوز نهاري."}},{"id":"sl5","dim":"sleep","text":{"fr":"Au moment de dormir, mon esprit reste très actif.","en":"My mind stays active when I try to fall asleep.","ar":"يبقى ذهني منشغلا عندما أحاول النوم.","darija":"ملي كنمشي ننعس، مخي كيبقى خدام."}},{"id":"sl6","dim":"sleep","text":{"fr":"J’essaie de compenser le manque de sommeil par la caféine ou de longues siestes.","en":"I try to make up for lost sleep with caffeine or long naps.","ar":"أحاول تعويض قلة النوم بالكافيين أو بقيلولات طويلة.","darija":"كنحاول نعوض قلة النعاس بالقهوة ولا بقيلولة طويلة."}}];

    const schemaBank = [{"id":"sc1","dim":"abandon","text":{"fr":"J’ai peur que des personnes importantes pour moi s’en aillent.","en":"I fear important people may leave me.","ar":"اخاف ان يتركني الاشخاص المهمون.","darija":"كنخاف الناس المهمين عندي يخلّيوّني."}},{"id":"sc2","dim":"abandon","text":{"fr":"Je me sens très anxieux·se quand une personne prend ses distances.","en":"I become very anxious when someone takes distance.","ar":"اشعر بقلق شديد عندما يبتعد شخص ما.","darija":"كنقلق بزاف ملي شي واحد كيبعد عليا."}},{"id":"sc3","dim":"rejection","text":{"fr":"Je me sens souvent rejeté·e sans élément clair qui le confirme.","en":"I often feel rejected without clear proof.","ar":"اشعر غالبا بالرفض دون دليل واضح.","darija":"كنحس بالرفض حتى بلا دليل واضح."}},{"id":"sc4","dim":"rejection","text":{"fr":"Je suppose rapidement que les autres me jugent négativement.","en":"I quickly assume others judge me negatively.","ar":"افترض بسرعة ان الاخرين يحكمون علي بسلبية.","darija":"كنفترض بسرعة الناس كيشوفوني بنظرة سلبية."}},{"id":"sc5","dim":"inferiority","text":{"fr":"Je me sens inférieur·e aux autres dans ma valeur personnelle.","en":"I feel inferior to others in personal worth.","ar":"اشعر ان قيمتي اقل من الاخرين.","darija":"كنحس راسي اقل قيمة من الناس."}},{"id":"sc6","dim":"inferiority","text":{"fr":"Je me critique durement pour de petites erreurs.","en":"I harshly criticize myself for small mistakes.","ar":"انتقد نفسي بقسوة بسبب اخطاء صغيرة.","darija":"كنقسي على راسي بزاف على اخطاء صغيرة."}},{"id":"sc7","dim":"perfectionism","text":{"fr":"Je crois devoir être parfait·e pour être accepté·e.","en":"I feel I must be perfect to be accepted.","ar":"اشعر ان علي ان اكون مثاليا حتى اقبل.","darija":"كنحس خاصني نكون كامل باش يتقبلوني."}},{"id":"sc8","dim":"perfectionism","text":{"fr":"Je remets des tâches à plus tard si je ne peux pas les faire parfaitement.","en":"I procrastinate when I cannot do things perfectly.","ar":"اؤجل المهام عندما لا استطيع تنفيذها بشكل مثالي.","darija":"كنأجل المهام ملي ما نقدرش نديرها كاملة."}},{"id":"sc9","dim":"dependence","text":{"fr":"J’ai du mal à prendre seul·e des décisions.","en":"I struggle to make decisions alone.","ar":"اجد صعوبة في اتخاذ القرارات وحدي.","darija":"كيصعب عليا ناخذ قرارات بوحدي."}},{"id":"sc10","dim":"dependence","text":{"fr":"Je cherche souvent à être rassuré·e avant d’agir.","en":"I constantly seek reassurance before acting.","ar":"ابحث دائما عن تطمين قبل التصرف.","darija":"ديما كنطلب الطمانينة قبل ما نتصرف."}},{"id":"sc11","dim":"mistrust","text":{"fr":"Je crains que les autres profitent de moi.","en":"I expect people to take advantage of me.","ar":"اتوقع ان يستغلني الناس.","darija":"كنتسنى الناس يستغلوّني."}},{"id":"sc12","dim":"mistrust","text":{"fr":"J’ai du mal à faire confiance, même dans une relation stable.","en":"I struggle to trust even in stable relationships.","ar":"اجد صعوبة في الثقة حتى في العلاقات المستقرة.","darija":"كيصعب عليا نثق حتى فالعلاقات المستقرة."}},{"id":"sc13","dim":"peoplepleasing","text":{"fr":"Je dis oui pour éviter un conflit, même lorsque cela va contre mes besoins.","en":"I say yes to avoid conflict, even against myself.","ar":"اقول نعم لتجنب الصراع حتى ضد مصلحتي.","darija":"كنقول نعم باش نهرب من الصداع حتى ضد راسي."}},{"id":"sc14","dim":"peoplepleasing","text":{"fr":"Je culpabilise quand je pose mes limites.","en":"I feel guilty when I set boundaries.","ar":"اشعر بالذنب عندما اضع حدودا.","darija":"كنحس بالذنب ملي كنحط الحدود."}},{"id":"sc15","dim":"emotionaldeprivation","text":{"fr":"J’ai souvent le sentiment que mes besoins affectifs ne sont pas compris.","en":"I often feel my emotional needs are not understood.","ar":"اشعر ان احتياجاتي العاطفية غير مفهومة.","darija":"كنحس الاحتياجات العاطفية ديالي ما مفهومةش."}}];

    const reflectionDimensions = ["emotion_awareness", "stress_recovery", "social_support", "boundaries", "daily_rhythm", "values_direction"];
    const reflectionLabels = {"fr":{"emotion_awareness":"Conscience emotionnelle","stress_recovery":"Recuperation après le stress","social_support":"Soutien social","boundaries":"Limites personnelles","daily_rhythm":"Rythme quotidien","values_direction":"Valeurs et direction"},"en":{"emotion_awareness":"Emotional awareness","stress_recovery":"Stress recovery","social_support":"Social support","boundaries":"Personal boundaries","daily_rhythm":"Daily rhythm","values_direction":"Values and direction"},"ar":{"emotion_awareness":"الوعي بالمشاعر","stress_recovery":"التعافي بعد الضغط","social_support":"الدعم الاجتماعي","boundaries":"الحدود الشخصية","daily_rhythm":"الإيقاع اليومي","values_direction":"القيم والاتجاه"},"darija":{"emotion_awareness":"الوعي بالمشاعر","stress_recovery":"الراحة من بعد الضغط","social_support":"الدعم من الناس","boundaries":"الحدود الشخصية","daily_rhythm":"الروتين اليومي","values_direction":"القيم والاتجاه"}};
    const reflectionBank = [{"id":"rf1","dim":"emotion_awareness","text":{"fr":"Je remarque ce que je ressens avant de réagir.","en":"I notice what I feel before I react.","ar":"ألاحظ ما أشعر به قبل أن أتصرف.","darija":"كنلاحظ شنو حاس قبل ما نرد الفعل."}},{"id":"rf2","dim":"emotion_awareness","text":{"fr":"Je trouve des mots pour décrire mon humeur.","en":"I can find words to describe my mood.","ar":"أستطيع إيجاد كلمات لوصف مزاجي.","darija":"كنقدر نلقى كلمات نوصف بها المزاج ديالي."}},{"id":"rf3","dim":"emotion_awareness","text":{"fr":"Je remarque les situations qui influencent mes émotions.","en":"I notice situations that influence my emotions.","ar":"ألاحظ المواقف التي تؤثر في مشاعري.","darija":"كنلاحظ المواقف اللي كتأثر على المشاعر ديالي."}},{"id":"rf4","dim":"emotion_awareness","text":{"fr":"Je peux accueillir une émotion sans me juger tout de suite.","en":"I can make room for a feeling without judging myself right away.","ar":"أستطيع تقبل شعور دون أن أحكم على نفسي فورا.","darija":"كنقدر نقبل الإحساس بلا ما نحكم على راسي دغيا."}},{"id":"rf5","dim":"stress_recovery","text":{"fr":"Après une journée exigeante, je trouve un moment pour souffler.","en":"After a demanding day, I find a moment to pause.","ar":"أجد لحظة للراحة بعد يوم مرهق.","darija":"كنلقى شوية ديال الوقت نرتاح من بعد نهار عامر."}},{"id":"rf6","dim":"stress_recovery","text":{"fr":"Je connais une activité simple qui m’aide à me détendre.","en":"I know a simple activity that helps me unwind.","ar":"أعرف نشاطا بسيطا يساعدني على الاسترخاء.","darija":"عارف شي نشاط بسيط كيساعدني نرتاح."}},{"id":"rf7","dim":"stress_recovery","text":{"fr":"Après un moment stressant, je reprends mes activités à mon rythme.","en":"I return to activities at my own pace after a stressful moment.","ar":"أعود إلى أنشطتي بإيقاعي بعد موقف ضاغط.","darija":"كنرجع للأنشطة ديالي بالوتيرة ديالي من بعد موقف فيه الضغط."}},{"id":"rf8","dim":"stress_recovery","text":{"fr":"Je peux demander une pause quand je me sens débordé·e.","en":"I can ask for a break when things feel demanding.","ar":"أستطيع طلب استراحة عندما تصبح الأمور مرهقة.","darija":"كنقدر نطلب راحة ملي كيولي الحمل تقيل."}},{"id":"rf9","dim":"social_support","text":{"fr":"J’ai au moins une personne à qui parler si j’en ai envie.","en":"I have at least one person I can talk to if I want.","ar":"لدي شخص واحد على الأقل يمكنني الحديث معه إذا رغبت.","darija":"كاين على الأقل شي واحد نقدر نهضر معاه إلا بغيت."}},{"id":"rf10","dim":"social_support","text":{"fr":"Je me sens écouté·e dans au moins une relation importante.","en":"I feel heard in at least one important relationship.","ar":"أشعر بأنني مسموع في علاقة مهمة واحدة على الأقل.","darija":"كنحس شي واحد كيسمع ليا فشي علاقة مهمة على الأقل."}},{"id":"rf11","dim":"social_support","text":{"fr":"Je peux accepter de l’aide quand j’en ai besoin.","en":"I can accept help when I need it.","ar":"أستطيع قبول المساعدة عندما أحتاجها.","darija":"كنقدر نقبل المساعدة ملي كنحتاجها."}},{"id":"rf12","dim":"social_support","text":{"fr":"Je garde le contact avec les personnes qui comptent pour moi.","en":"I stay connected with people who matter to me.","ar":"أحافظ على التواصل مع أشخاص مهمين بالنسبة لي.","darija":"كنبقى على تواصل مع الناس اللي مهمين عندي."}},{"id":"rf13","dim":"boundaries","text":{"fr":"Je peux dire non quand une demande ne me convient pas.","en":"I can say no when a request does not work for me.","ar":"أستطيع قول لا عندما لا يناسبني طلب ما.","darija":"كنقدر نقول لا ملي شي طلب ما مناسبنيش."}},{"id":"rf14","dim":"boundaries","text":{"fr":"J’exprime mes besoins de manière assez claire.","en":"I express my needs fairly clearly.","ar":"أعبّر عن احتياجاتي بوضوح معقول.","darija":"كنعبر على الاحتياجات ديالي بوضوح معقول."}},{"id":"rf15","dim":"boundaries","text":{"fr":"Je remarque quand j’ai besoin de temps ou d’espace.","en":"I notice when I need time or space.","ar":"ألاحظ عندما أحتاج إلى وقت أو مساحة خاصة.","darija":"كنلاحظ ملي كنحتاج الوقت ولا المساحة ديالي."}},{"id":"rf16","dim":"boundaries","text":{"fr":"Je peux parler d’un désaccord en respectant mes besoins et ceux de l’autre.","en":"I can discuss a disagreement with respect for myself and the other person.","ar":"أستطيع مناقشة الخلاف باحترام لنفسي وللآخر.","darija":"كنقدر نهضر على الاختلاف باحترام لراسي وللشخص الآخر."}},{"id":"rf17","dim":"daily_rhythm","text":{"fr":"Mon rythme de sommeil m’aide souvent à récupérer.","en":"My sleep routine often gives me a chance to recover.","ar":"يساعدني نمط نومي غالبا على استعادة طاقتي.","darija":"نظام النعاس ديالي كيساعدني غالبا نرجع النشاط."}},{"id":"rf18","dim":"daily_rhythm","text":{"fr":"Je prends des pauses dans la journée quand c’est possible.","en":"I take breaks during my day when possible.","ar":"آخذ استراحات خلال يومي عندما يكون ذلك ممكنا.","darija":"كندير استراحات فالنهار ديالي ملي كيكون ممكن."}},{"id":"rf19","dim":"daily_rhythm","text":{"fr":"J’arrive à garder quelques habitudes qui me font du bien.","en":"I can keep a few routines that are good for me.","ar":"أستطيع الحفاظ على بعض العادات المفيدة لي.","darija":"كنقدر نحافظ على شي عادات اللي كتنفعني."}},{"id":"rf20","dim":"daily_rhythm","text":{"fr":"Je trouve un peu de temps pour une activité qui me ressource.","en":"I find some time for an activity that replenishes me.","ar":"أجد بعض الوقت لنشاط يساعدني على استعادة طاقتي.","darija":"كنلقى شوية ديال الوقت لشي نشاط كيرجع ليا الطاقة."}},{"id":"rf21","dim":"values_direction","text":{"fr":"Je peux nommer une ou deux choses qui comptent pour moi.","en":"I can name one or two things that matter to me.","ar":"أستطيع تحديد أمر أو أمرين مهمين بالنسبة لي.","darija":"كنقدر نسمي حاجة ولا جوج اللي مهمين عندي."}},{"id":"rf22","dim":"values_direction","text":{"fr":"Certains de mes choix quotidiens reflètent ce qui compte pour moi.","en":"Some of my everyday choices reflect what matters to me.","ar":"تعكس بعض اختياراتي اليومية ما يهمني.","darija":"شي اختيارات يومية ديالي كتعكس شنو مهم عندي."}},{"id":"rf23","dim":"values_direction","text":{"fr":"Je me donne un petit objectif qui a du sens pour moi.","en":"I set a small goal that feels meaningful to me.","ar":"أضع هدفا صغيرا له معنى بالنسبة لي.","darija":"كنحط هدف صغير عندو معنى بالنسبة ليا."}},{"id":"rf24","dim":"values_direction","text":{"fr":"Je peux ajuster mes priorités quand ma situation change.","en":"I can adjust my priorities when my situation changes.","ar":"أستطيع تعديل أولوياتي عندما تتغير ظروفي.","darija":"كنقدر نبدل الأولويات ديالي ملي كتبدل الظروف."}}];

