    const fullAssessmentSessionKey = "mc-full-assessment-session";
    const fullAssessmentDraftPrefix = "mc-full-assessment-draft-";
    let activeFullAssessmentInterpretationCopy = null;

    function fullAssessmentText() {
      return fullAssessmentCopy[state.lang] || fullAssessmentCopy.en;
    }

    function isFullAssessmentFlow() {
      return new URLSearchParams(window.location.search).get("flow") === "full";
    }

    function readFullAssessmentSession() {
      try {
        const saved = JSON.parse(localStorage.getItem(fullAssessmentSessionKey) || "null");
        return saved && typeof saved === "object" && Array.isArray(saved.completed) ? saved : null;
      } catch {
        return null;
      }
    }

    function startFullAssessment() {
      localStorage.setItem(fullAssessmentSessionKey, JSON.stringify({ startedAt: new Date().toISOString(), completed: [] }));
      ["assessment", "schema-form", "reflection-form"].forEach((formId) => localStorage.removeItem(`${fullAssessmentDraftPrefix}${formId}`));
      localStorage.removeItem("mc-active-question-set");
      ["assessment-form", "schema-form", "reflection-form"].forEach((formId) => document.getElementById(formId)?.reset());
      state.assessmentAnswers = {};
      state.activeQuestions = [];
      state.activeSchemaQuestions = [];
      state.activeReflectionQuestions = [];
    }

    function readFullAssessmentDraft(formId) {
      if (!isFullAssessmentFlow()) return {};
      try {
        const saved = JSON.parse(localStorage.getItem(`${fullAssessmentDraftPrefix}${formId}`) || "{}");
        if (!saved || typeof saved !== "object" || Array.isArray(saved)) return {};
        return Object.fromEntries(Object.entries(saved).filter(([name, value]) => typeof name === "string" && ["0", "1", "2", "3"].includes(String(value))));
      } catch {
        return {};
      }
    }

    function storeFullAssessmentDraft(formId) {
      if (!isFullAssessmentFlow()) return;
      const form = document.getElementById(formId);
      if (!form) return;
      const answers = Object.fromEntries([...form.querySelectorAll('input[type="radio"]:checked')].map((input) => [input.name, input.value]));
      localStorage.setItem(`${fullAssessmentDraftPrefix}${formId}`, JSON.stringify(answers));
    }

    function finishFullAssessmentStep(type) {
      const session = readFullAssessmentSession() || { startedAt: new Date().toISOString(), completed: [] };
      session.completed = [...new Set([...session.completed, type])];
      const nextPage = { assessment: "schemas", schema: "reflection", reflection: "results" }[type];
      if (type === "reflection") session.finishedAt = new Date().toISOString();
      localStorage.setItem(fullAssessmentSessionKey, JSON.stringify(session));
      const formId = { assessment: "assessment", schema: "schema-form", reflection: "reflection-form" }[type];
      if (formId) localStorage.removeItem(`${fullAssessmentDraftPrefix}${formId}`);
      navigateToAppUrl(new URL(`?page=${nextPage}&flow=full`, window.location.href));
    }

