    function renderFullAssessmentProgress() {
      document.getElementById("full-assessment-progress")?.remove();
      if (!isFullAssessmentFlow()) return;
      const stages = {
        assessment: { section: "assessment", title: "assessment.title" },
        schemas: { section: "schema-test", title: "schemas.title" },
        reflection: { section: "reflection-test", title: "reflection.title" }
      };
      const stage = stages[state.page];
      if (!stage) return;
      const index = Object.keys(stages).indexOf(state.page);
      const copy = fullAssessmentText();
      const panel = document.createElement("aside");
      panel.id = "full-assessment-progress";
      panel.className = "mx-auto mb-6 max-w-6xl rounded-xl border border-amber-200/20 bg-amber-100/5 px-5 py-4";
      panel.setAttribute("aria-label", `${copy.step} ${index + 1} ${copy.of} 3`);
      const header = document.createElement("div");
      header.className = "flex flex-wrap items-center justify-between gap-2 text-sm";
      const label = document.createElement("span");
      label.className = "text-slate-300";
      label.textContent = `${copy.step} ${index + 1} ${copy.of} 3 · ${t(stage.title)}`;
      const count = document.createElement("strong");
      count.className = "text-amber-100";
      count.textContent = `${index + 1} / 3`;
      header.append(label, count);
      const track = document.createElement("div");
      track.className = "mt-3 h-1.5 overflow-hidden rounded-full bg-white/10";
      track.setAttribute("role", "progressbar");
      track.setAttribute("aria-valuemin", "0");
      track.setAttribute("aria-valuemax", "3");
      track.setAttribute("aria-valuenow", String(index));
      const fill = document.createElement("span");
      fill.className = "block h-full rounded-full bg-amber-200 transition-all duration-500";
      fill.style.width = `${(index / 3) * 100}%`;
      track.appendChild(fill);
      panel.append(header, track);
      const cover = document.querySelector(`#${stage.section} .page-cover`);
      cover?.insertAdjacentElement("afterend", panel);
    }

