    function renderAccountResults(data) {
      const target = $("#account-saved-results");
      target.replaceChildren();
      const rows = [
        ...data.assessments.map((result) => ({ ...result, kind: "assessment" })),
        ...data.schemas.map((result) => ({ ...result, kind: "schema" })),
        ...(data.reflections || []).map((result) => ({ ...result, kind: "reflection" }))
      ].sort((a, b) => new Date(b.date) - new Date(a.date));
      if (!rows.length) {
        const empty = document.createElement("p");
        empty.className = "text-sm text-slate-400";
        empty.textContent = t("account.noSavedResults");
        target.appendChild(empty);
        return;
      }
      rows.slice(0, 20).forEach((result) => {
        const article = document.createElement("article");
        article.className = "rounded-md border border-white/10 bg-slate-900/45 p-3";
        const heading = document.createElement("h4");
        heading.className = "font-medium";
        heading.textContent = `${t(result.kind === "assessment" ? "nav.assessment" : "nav.schemas")} · ${formatResultDate(result.date)}`;
        const scores = document.createElement("p");
        scores.className = "mt-1 text-sm text-slate-300";
        const labels = result.kind === "assessment" ? null
          : result.kind === "schema" ? window.schemaLabels[state.lang] : reflectionLabels[state.lang];
        scores.textContent = Object.entries(result.scores)
          .map(([key, score]) => `${labels ? labels[key] : t(`common.${key}`)}: ${typeof score === "number" ? score : score.score}/9`)
          .join(" · ");
        article.append(heading, scores);
        target.appendChild(article);
      });
    }

    function renderWeeklyReports(reports) {
      const target = $("#weekly-report-list");
      target.replaceChildren();
      if (!reports.length) {
        const empty = document.createElement("p");
        empty.className = "text-sm text-slate-400";
        empty.textContent = t("account.noReports");
        target.appendChild(empty);
        return;
      }
      reports.forEach(({ weekStart, report }) => {
        const article = document.createElement("article");
        article.className = "rounded-md border border-white/10 bg-slate-900/45 p-4";
        const heading = document.createElement("h4");
        heading.className = "font-medium";
        heading.textContent = `${t("account.reportStart")} ${formatResultDate(weekStart)}`;
        const counts = document.createElement("p");
        counts.className = "mt-2 text-sm text-slate-300";
        counts.textContent = `${t("account.reportAssessmentCount")}: ${report.assessmentCount} · ${t("account.reportSchemaCount")}: ${report.schemaCount} · ${t("reflection.title")}: ${report.reflectionCount || 0}`;
        article.append(heading, counts);
        const sections = [
          ["assessmentChange", ["stress", "anxiety", "dépression", "sleep"], null],
          ["schemaChange", Object.keys(window.schemaLabels[state.lang]), window.schemaLabels[state.lang]],
          ["reflectionChange", reflectionDimensions, reflectionLabels[state.lang]]
        ];
        let hasChanges = false;
        sections.forEach(([property, dimensions, labels]) => {
          const changes = report[property];
          if (!changes) return;
          hasChanges = true;
          const paragraph = document.createElement("p");
          paragraph.className = "mt-2 text-sm text-slate-200";
          const changeLines = dimensions.filter((key) => changes[key]).map((key) => {
            const item = changes[key];
            const delta = item.change > 0 ? `+${item.change}` : String(item.change);
            return `${labels ? labels[key] : t(`common.${key}`)}: ${item.previousWeek} ? ${item.latest} (${delta})`;
          });
          paragraph.textContent = `${t("account.reportChange")}: ${changeLines.join(" · ")}`;
          article.appendChild(paragraph);
        });
        if (!hasChanges) {
          const noCompare = document.createElement("p");
          noCompare.className = "mt-2 text-sm text-slate-300";
          noCompare.textContent = t("account.latestOnly");
          article.appendChild(noCompare);
        }
        const note = document.createElement("p");
        note.className = "mt-3 border-t border-white/10 pt-3 text-xs text-slate-400";
        note.textContent = t("account.reportNote");
        article.appendChild(note);
        target.appendChild(article);
      });
    }

    async function loadAccountData() {
      const [results, weekly] = await Promise.all([
        accountRequest("/api/results"),
        accountRequest("/api/weekly-reports")
      ]);
      renderAccountResults(results);
      renderWeeklyReports(weekly.reports);
    }

    async function setAuthenticatedAccount(user, message) {
      state.accountUser = user;
      $("#account-guest").classList.add("hidden");
      $("#account-authenticated").classList.remove("hidden");
      $("#account-email").textContent = user.email;
      $("#account-weekly-toggle").checked = user.weeklyReports;
      setAccountStatus(message);
      await loadAccountData();
    }

    async function initializeAccount() {
      if (window.location.protocol === "file:") {
        setAccountStatus(t("account.serverUnavailable"), true);
        return;
      }
      try {
        const response = await fetch("/api/session", { credentials: "same-origin", cache: "no-store" });
        if (response.status === 401) return;
        if (!response.ok) throw new Error(t("account.serverUnavailable"));
        const { user } = await response.json();
        if (!user) return;
        await setAuthenticatedAccount(user, t("account.loginSuccess"));
      } catch (error) {
        setAccountStatus(error.message || t("account.serverUnavailable"), true);
      }
    }

    async function syncGuestResults() {
      const assessments = getGuestAssessments();
      for (const result of assessments) {
        await accountRequest("/api/assessment-results", {
          method: "POST",
          body: JSON.stringify({ scores: result.scores, mode: result.mode })
        });
      }
      const schemaRaw = JSON.parse(localStorage.getItem("mc-combined-schema") || "null");
      if (schemaRaw?.scores) {
        const analysis = schemaAnalysis(schemaRaw.scores);
        await accountRequest("/api/schema-results", {
          method: "POST",
          body: JSON.stringify({ scores: analysis.normalizedByDim })
        });
      }
      const reflectionRaw = JSON.parse(localStorage.getItem("mc-combined-reflection") || "null");
      if (reflectionRaw?.scores) {
        await accountRequest("/api/reflection-results", {
          method: "POST",
          body: JSON.stringify({ scores: reflectionRaw.scores })
        });
      }
    }

    function applyPageLayout() {
      const allowedPages = ["home", "assessment", "schemas", "reflection", "mental-health", "methods", "breathing", "sleep", "results", "references", "login"];
      if (!allowedPages.includes(state.page)) state.page = "home";
      document.body.dataset.page = state.page;
      const welcomeIntro = $("#welcome-intro");
      const showWelcomeIntro = state.page === "home" && !hasSeenWelcomeIntro();
      if (showWelcomeIntro) document.body.setAttribute("data-home-intro", "true");
      else document.body.removeAttribute("data-home-intro");
      welcomeIntro.hidden = !showWelcomeIntro;
      welcomeIntro.setAttribute("aria-hidden", String(!showWelcomeIntro));
      const pageSection = {
        assessment: "assessment",
        schemas: "schema-test",
        reflection: "reflection-test",
        "mental-health": "mental-health-checkin",
        methods: "methods",
        breathing: "breathing",
        sleep: "sleep",
        results: "combined-results",
        references: "references",
        login: "account-page"
      }[state.page];

      Array.from($("#top").children)
        .filter((el) => el.tagName === "SECTION")
        .forEach((section) => {
          const isHidden = section.id === "welcome-intro"
            ? !showWelcomeIntro
            : state.page === "home"
            ? ["combined-results", "account-page", "assessment", "schema-test", "reflection-test", "mental-health-checkin", "dashboard", "methods", "breathing", "sleep", "references"].includes(section.id)
            : section.id !== pageSection;
          section.hidden = isHidden;
          section.classList.toggle("hidden", isHidden);
        });
      $$("[data-nav-page]").forEach((link) => {
        const isCurrentPage = link.dataset.navPage === state.page;
        const isCurrentSection = state.page === "home" && link.dataset.navSection === window.location.hash.slice(1);
        if (isCurrentPage || isCurrentSection) {
          link.setAttribute("aria-current", isCurrentPage ? "page" : "location");
        } else {
          link.removeAttribute("aria-current");
        }
      });
      updateWorkspaceHeader();
      renderFullAssessmentProgress();
      updateResultsPageLayout();
    }

    function animateRouteContent() {
      if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
      const homeTargets = ["main-home", "daily-note", "home-dashboard", "home-tests"]
        .map((id) => document.getElementById(id));
      const pageTargetIds = {
        assessment: "assessment",
        schemas: "schema-test",
        reflection: "reflection-test",
        "mental-health": "mental-health-checkin",
        methods: "methods",
        breathing: "breathing",
        sleep: "sleep",
        results: state.resultsDetail ? "results-detail" : "combined-results",
        references: "references",
        login: "account-page"
      };
      const targets = state.page === "home"
        ? homeTargets
        : [document.getElementById(pageTargetIds[state.page])];
      targets.filter((target) => target && !target.hidden).forEach((target, index) => {
        target.classList.remove("route-entering");
        target.style.setProperty("--route-enter-delay", `${index * 55}ms`);
        void target.offsetWidth;
        target.classList.add("route-entering");
        window.setTimeout(() => {
          target.classList.remove("route-entering");
          target.style.removeProperty("--route-enter-delay");
        }, 520);
      });
    }

    function renderRouteFromLocation({ scrollToTop = false, animate = true } = {}) {
      const params = new URLSearchParams(window.location.search);
      state.page = params.get("page") || "home";
      state.resultsDetail = params.get("detail") || "";
      state.schemaFocus = params.get("topic") || "";
      document.body.classList.remove("presentation-leaving");
      applyPageLayout();
      applyTranslations();
      restoreLatestAssessmentResult();
      renderHomeProgress();
      renderDaypartNote();
      replayVisibleReveals();
      if (animate) animateRouteContent();
      if (scrollToTop) {
        if (window.location.hash) {
          requestAnimationFrame(() => document.querySelector(window.location.hash)?.scrollIntoView({ block: "start" }));
        } else {
          window.scrollTo(0, 0);
        }
        const activeSection = document.querySelector("#top > section:not([hidden])");
        const heading = activeSection?.querySelector("#results-detail-title") || activeSection?.querySelector("h1");
        if (heading) {
          heading.tabIndex = -1;
          heading.focus({ preventScroll: true });
        }
      }
      measureScrollRange();
      updateScrollProgress();
    }

    function navigateToAppUrl(url, { scrollToTop = true, replace = false } = {}) {
      if (!(url instanceof URL) || url.origin !== window.location.origin) return;
      const method = replace ? "replaceState" : "pushState";
      window.history[method]({ page: url.searchParams.get("page") || "home" }, "", `${url.pathname}${url.search}${url.hash}`);
      renderRouteFromLocation({ scrollToTop });
    }

