    function renderAssessmentModeCopy() {
      const copy = assessmentModeCopy[state.lang] || assessmentModeCopy.en;
      const mode = $("#analysis-mode")?.value || "quick";
      const subtitle = $("#assessment-subtitle");
      const description = $("#assessment-mode-description");
      const duration = document.querySelector('[data-i18n="exerciseGuide.assessmentDuration"]');
      if (subtitle) subtitle.textContent = copy.subtitle;
      if (description) description.textContent = copy.modes[mode] || copy.modes.quick;
      if (duration) duration.textContent = copy.durations[mode] || copy.durations.quick;
      const progressLabel = $("#assessment-progress-label");
      if (progressLabel) progressLabel.textContent = copy.progress;
      updateAssessmentProgress();
    }

    function updateAssessmentProgress() {
      const counter = $("#assessment-progress-count");
      const bar = $("#assessment-progress-bar");
      if (!counter || !bar) return;
      const mode = $("#analysis-mode")?.value || "quick";
      const total = state.activeQuestions.length || (mode === "detailed" ? 24 : 12);
      const answers = Object.fromEntries(new FormData($("#assessment-form")).entries());
      const answered = state.activeQuestions.filter((question) => ["0", "1", "2", "3"].includes(answers[question.id])).length;
      const copy = assessmentModeCopy[state.lang] || assessmentModeCopy.en;
      counter.textContent = `${answered} / ${total}`;
      bar.setAttribute("aria-valuemax", String(total));
      bar.setAttribute("aria-valuenow", String(answered));
      bar.setAttribute("aria-label", `${copy.progress}: ${copy.progressValue.replace("{done}", String(answered)).replace("{total}", String(total))}`);
      bar.firstElementChild.style.width = `${total ? (answered / total) * 100 : 0}%`;
    }

