    function scoreReflection(responses) {
      const totals = Object.fromEntries(reflectionDimensions.map((dimension) => [dimension, 0]));
      responses.forEach(({ dimension, score }) => { totals[dimension] += score; });
      return Object.fromEntries(reflectionDimensions.map((dimension) => [
        dimension,
        Math.round((totals[dimension] / 4) * 30) / 10
      ]));
    }

    function renderReflectionResults(scores) {
      const ordered = reflectionDimensions.map((key) => [key, scores[key]]).sort((a, b) => b[1] - a[1]);
      const highest = ordered[0][1];
      const lowest = ordered[ordered.length - 1][1];
      const mostReported = ordered.filter(([, score]) => score === highest);
      const lessReported = ordered.filter(([, score]) => score === lowest);
      $("#reflection-result-summary").textContent = `${t("reflection.summary")} ${mostReported.map(([key]) => reflectionLabels[state.lang][key]).join(", ")}.`;
      $("#reflection-result-profile").textContent = `${t("reflection.profile")} ${lessReported.map(([key]) => reflectionLabels[state.lang][key]).join(", ")}. ${t("reflection.scoreMethod")}.`;
      const rows = $("#reflection-result-scores");
      rows.replaceChildren();
      ordered.forEach(([key, score]) => {
        const row = document.createElement("div");
        const header = document.createElement("div");
        header.className = "mb-1 flex justify-between gap-3 text-sm";
        const label = document.createElement("span");
        label.textContent = reflectionLabels[state.lang][key];
        const value = document.createElement("span");
        value.textContent = `${score.toFixed(1)} / 9`;
        header.append(label, value);
        const track = document.createElement("div");
        track.className = "h-2 overflow-hidden rounded-full bg-white/10";
        const fill = document.createElement("div");
        fill.className = "h-full rounded-full bg-cyan-400";
        fill.style.width = `${Math.round((score / 9) * 100)}%`;
        track.appendChild(fill);
        row.append(header, track);
        rows.appendChild(row);
      });
      const prompts = $("#reflection-result-prompts");
      prompts.replaceChildren();
      [...new Set([...mostReported, ...lessReported].map(([key]) => key))].forEach((key) => {
        const item = document.createElement("li");
        item.textContent = `${reflectionLabels[state.lang][key]}: ${t(`reflection.prompts.${key}`)}`;
        prompts.appendChild(item);
      });
    }

