      const labels = {"fr":{"abandon":"Peur d'abandon","rejection":"Schema de rejet","inferiority":"Schema d'inferiorite","perfectionism":"Perfectionnisme rigide","dependence":"Dependance decisionnelle","mistrust":"Mefiance relationnelle","peoplepleasing":"Sur-adaptation","emotionaldeprivation":"Privation emotionnelle"},"en":{"abandon":"Abandonment fear","rejection":"Rejection schema","inferiority":"Inferiority schema","perfectionism":"Rigid perfectionism","dependence":"Decision dependence","mistrust":"Relational mistrust","peoplepleasing":"People pleasing","emotionaldeprivation":"Emotional deprivation"},"ar":{"abandon":"خوف الهجر","rejection":"مخطط الرفض","inferiority":"مخطط الدونية","perfectionism":"الكمالية الصارمة","dependence":"اعتماد مفرط في القرار","mistrust":"عدم الثقة العلائقية","peoplepleasing":"ارضاء الاخرين","emotionaldeprivation":"حرمان عاطفي"},"darija":{"abandon":"الخوف من الهجر","rejection":"مخطط الرفض","inferiority":"مخطط النقص","perfectionism":"الكمالية الصارمة","dependence":"اعتماد زايد فالقرار","mistrust":"نقص الثقة فالعلاقات","peoplepleasing":"ارضاء الناس","emotionaldeprivation":"حرمان عاطفي"}};

