    function renderAssessmentBoardMeta(scores, date) {
      const copy = assessmentBoardCopy();
      const set = (id, value) => { const element = document.getElementById(id); if (element) element.textContent = value; };
      const locale = { fr: "fr-FR", en: "en-US", ar: "ar", darija: "ar-MA" }[state.lang] || "fr-FR";
      const dimensions = ["stress", "anxiety", "dépression", "sleep"];
      const average = dimensions.reduce((total, key) => total + scores[key].score, 0) / dimensions.length;
      const formatAverage = (value) => new Intl.NumberFormat(locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(value);
      const highest = dimensions.reduce((best, key) => scores[key].score > scores[best].score ? key : best, dimensions[0]);
      const actualDate = date || JSON.parse(localStorage.getItem("mc-combined-assessment") || "null")?.date || new Date().toISOString();
      const parsedDate = new Date(actualDate);

      set("assessment-board-eyebrow", copy.eyebrow);
      document.getElementById("assessment-board-kpis").setAttribute("aria-label", copy.overview);
      set("assessment-average-label", copy.average);
      set("assessment-average-value", `${formatAverage(average)} / 9`);
      set("assessment-average-hint", copy.averageHint);
      set("assessment-domains-label", copy.domains);
      set("assessment-domains-value", "4");
      set("assessment-domains-hint", copy.domainsHint);
      set("assessment-focus-label", copy.focus);
      set("assessment-focus-value", t(`common.${highest}`));
      set("assessment-focus-hint", copy.focusHint);
      renderAssessmentGuidance(highest);
      set("assessment-scores-eyebrow", copy.scoresEyebrow);
      set("assessment-scores-heading", copy.scoresTitle);
      set("assessment-history-eyebrow", copy.historyEyebrow);
      set("assessment-history-heading", copy.historyTitle);
      const dateElement = document.getElementById("assessment-result-date");
      dateElement.dateTime = Number.isNaN(parsedDate.valueOf()) ? "" : parsedDate.toISOString();
      dateElement.textContent = Number.isNaN(parsedDate.valueOf()) ? "" : new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short" }).format(parsedDate);

      const historyBox = document.getElementById("assessment-result-history");
      historyBox.replaceChildren();
      const history = getGuestAssessments().filter((item) => item?.date && item.scores
        && dimensions.every((key) => Number.isFinite(Number(item.scores[key]?.score)) && Number(item.scores[key]?.max) > 0))
        .slice(-5);
      const entries = history.map((item) => ({
        date: item.date,
        average: dimensions.reduce((total, key) => total + (Number(item.scores[key].score) / Number(item.scores[key].max)) * 9, 0) / dimensions.length
      }));

      if (!entries.length) {
        const empty = document.createElement("p");
        empty.className = "history-empty";
        empty.textContent = copy.noHistory;
        historyBox.appendChild(empty);
      } else {
        const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
        svg.setAttribute("viewBox", "0 0 100 72");
        svg.setAttribute("role", "img");
        svg.setAttribute("aria-label", copy.chartLabel);
        [17, 39, 61].forEach((y) => {
          const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
          line.setAttribute("x1", "3"); line.setAttribute("x2", "97"); line.setAttribute("y1", String(y)); line.setAttribute("y2", String(y));
          line.setAttribute("class", "history-chart-grid"); svg.appendChild(line);
        });
        const points = entries.map((item, index) => ({
          x: entries.length === 1 ? 50 : 6 + (index / (entries.length - 1)) * 88,
          y: 61 - (Math.max(0, Math.min(9, item.average)) / 9) * 44
        }));
        if (points.length > 1) {
          const line = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
          line.setAttribute("points", points.map((point) => `${point.x},${point.y}`).join(" "));
          line.setAttribute("class", "history-chart-line"); svg.appendChild(line);
        }
        points.forEach((point) => {
          const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
          circle.setAttribute("cx", String(point.x)); circle.setAttribute("cy", String(point.y)); circle.setAttribute("r", "2.6");
          circle.setAttribute("class", "history-chart-point"); svg.appendChild(circle);
        });
        historyBox.appendChild(svg);

        const rows = document.createElement("div");
        rows.className = "assessment-history-entries";
        entries.slice().reverse().slice(0, 3).forEach((item) => {
          const row = document.createElement("div");
          row.className = "assessment-history-entry";
          const stamp = document.createElement("span");
          const itemDate = new Date(item.date);
          stamp.textContent = Number.isNaN(itemDate.valueOf()) ? "" : new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" }).format(itemDate);
          const value = document.createElement("strong");
          value.textContent = `${formatAverage(item.average)} / 9`;
          row.append(stamp, value); rows.appendChild(row);
        });
        historyBox.appendChild(rows);
      }

      const historyLength = history.length;
      const focusValue = document.getElementById("assessment-focus-card-value");
      const focusHint = document.getElementById("assessment-focus-card-hint");
      if (historyLength > 1) {
        const change = entries[historyLength - 1].average - entries[historyLength - 2].average;
        set("assessment-focus-card-label", copy.focusCard);
        focusValue.textContent = `${change > 0 ? "+" : ""}${formatAverage(change)} / 9`;
        focusHint.textContent = copy.changeHint;
      } else {
        set("assessment-focus-card-label", copy.firstPoint);
        focusValue.textContent = copy.recorded;
        focusHint.textContent = copy.firstPointHint;
      }
    }

