      const context = methodContextByLang[state.lang]?.[dimension] || methodContextByLang.en[dimension];
      const method = methodsByLang[state.lang]?.[dimension] || methodsByLang.en[dimension];
      const duration = methodDurationByLang[state.lang]?.[dimension] || methodDurationByLang.en[dimension];
      const set = (id, value) => { const element = document.getElementById(id); if (element) element.textContent = value; };
      set("assessment-guidance-eyebrow", copy.resultEyebrow);
