      set("assessment-guidance-intro", copy.resultIntro);
      set("assessment-guidance-definition-label", copy.definition);
      set("assessment-guidance-definition", context.definition);
      set("assessment-guidance-influences-label", copy.influences);
      set("assessment-guidance-influences", context.influences);
      set("assessment-guidance-effects-label", copy.effects);
      set("assessment-guidance-effects", context.effects);
      set("assessment-guidance-action-label", copy.action);
