    function renderAssessmentResult(scores, summary, date) {
      $("#assessment-result-summary").textContent = summary;
      const scoreCards = $("#assessment-result-scores");
      scoreCards.replaceChildren();
      const levels = {"low":{"label":"resultLow","tone":"border-emerald-300/30 bg-emerald-500/5","badge":"border-emerald-300/40 bg-emerald-500/10 text-emerald-100","bar":"bg-emerald-400"},"moderate":{"label":"resultModerate","tone":"border-yellow-300/30 bg-yellow-500/5","badge":"border-yellow-300/40 bg-yellow-500/10 text-yellow-100","bar":"bg-yellow-400"},"high":{"label":"resultHigh","tone":"border-orange-300/30 bg-orange-500/5","badge":"border-orange-300/40 bg-orange-500/10 text-orange-100","bar":"bg-orange-400"},"severe":{"label":"resultSevere","tone":"border-rose-300/30 bg-rose-500/5","badge":"border-rose-300/40 bg-rose-500/10 text-rose-100","bar":"bg-rose-400"}};
      ["stress", "anxiety", "dépression", "sleep"].forEach((key) => {
        const item = scores[key];
        const level = levels[item.level];
        const card = document.createElement("div");
        card.className = `rounded-lg border p-4 ${level.tone}`;

        const header = document.createElement("div");
        header.className = "flex flex-wrap items-center justify-between gap-2";
        const label = document.createElement("span");
        label.className = "font-medium";
        label.textContent = t(`common.${key}`);
        const score = document.createElement("span");
        score.className = "text-sm text-slate-300";
        score.textContent = `${item.score} / ${item.max}`;
        header.append(label, score);

        const badge = document.createElement("span");
        badge.className = `mt-3 inline-block rounded-full border px-2.5 py-1 text-xs font-medium ${level.badge}`;
        badge.textContent = t(`assessment.${level.label}`);

        const track = document.createElement("div");
        track.className = "mt-3 h-2 overflow-hidden rounded-full bg-white/10";
        const fill = document.createElement("div");
        fill.className = `h-full rounded-full ${level.bar}`;
        fill.style.width = `${Math.min(100, Math.round((item.score / item.max) * 100))}%`;
        track.appendChild(fill);
        card.append(header, badge, track);
        scoreCards.appendChild(card);
      });
      renderAssessmentBoardMeta(scores, date);
    }

    function updateResults(scores, mode, date, previousSnapshot, questionIds = state.lastResult?.questionIds || []) {
      const bars = $("#score-bars");
      bars.innerHTML = "";
      const order = ["stress", "anxiety", "dépression", "sleep"];
      order.forEach((key) => {
        const item = scores[key];
        const sev = t(`common.${item.level}`);
        const width = Math.min(100, Math.round((item.score / item.max) * 100));
        bars.innerHTML += `<div><div class="mb-1 flex justify-between text-sm"><span>${t(`common.${key}`)}</span><span>${item.score}/${item.max} (${sev})</span></div><div class="h-2 rounded-full bg-white/10"><div class="h-2 rounded-full bg-cyan-400" style="width:${width}%"></div></div></div>`;
      });

      const interpretation = buildResultInterpretation(scores, mode);
      const report = buildClinicalReport(scores, mode, interpretation);
      $("#result-summary").textContent = interpretation.summary;
      renderAssessmentResult(scores, interpretation.summary, date);
      const saved = getGuestAssessments();
      const previous = previousSnapshot === undefined
        ? saved.slice().reverse().find((item) => item.date !== date && item.mode === "comparative" && sameQuestionSet(item.questionIds, questionIds))
        : previousSnapshot;
      const hasComparablePrevious = mode === "comparative" && previous?.mode === "comparative"
        && sameQuestionSet(previous.questionIds, questionIds) && previous.scores
        && assessmentDimensions.every((key) => previous.scores[key]?.max === 9);
      if (mode === "comparative") {
        const copy = assessmentModeCopy[state.lang] || assessmentModeCopy.en;
        const locale = { fr: "fr-FR", en: "en-US", ar: "ar", darija: "ar-MA" }[state.lang] || "fr-FR";
        const comparison = hasComparablePrevious
          ? `${copy.comparePrevious}: ${assessmentDimensions.map((key) => {
            const difference = Math.round((scores[key].score - previous.scores[key].score) * 10) / 10;
            const formatted = new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(Math.abs(difference));
            return `${t(`common.${key}`)} ${difference > 0 ? "+" : difference < 0 ? "−" : ""}${formatted}`;
          }).join(", ")}`
          : copy.compareFirst;
        $("#result-insight").textContent = `${interpretation.summary} ${comparison}`;
      } else {
        $("#result-insight").textContent = interpretation.summary;
      }
      $("#action-plan").innerHTML = interpretation.plan.map((s) => `<li>${s}</li>`).join("");
      renderClinicalReport(report, interpretation.level);
      renderHistory();
    }

    function restoreLatestAssessmentResult() {
      if (state.page !== "results") return;
      const saved = JSON.parse(localStorage.getItem("mc-combined-assessment") || "null");
      if (!saved?.scores || !["stress", "anxiety", "dépression", "sleep"].every((key) => saved.scores[key])) return;
      const mode = saved.mode || "quick";
      const previous = mode === "comparative"
        ? getGuestAssessments().slice().reverse().find((item) => item.date !== saved.date && item.mode === "comparative" && sameQuestionSet(item.questionIds, saved.questionIds)) || null
        : null;
      state.lastResult = { scores: saved.scores, mode, date: saved.date, questionIds: saved.questionIds || [] };
      updateResults(saved.scores, mode, saved.date, previous, saved.questionIds || []);
      $("#assessment-result").classList.remove("hidden");
    }

    function scheduleResultReveal(type) {
      const targets = {
        assessment: ["#assessment-form", "#assessment-result-status", "#assessment-result", "#assessment-result-title"],
        schema: ["#schema-form", "#schema-result-status", "#schema-results", "#schema-result-heading"],
        reflection: ["#reflection-form", "#reflection-result-status", "#reflection-results", "#reflection-result-heading"]
      };
      const [formSelector, statusSelector, resultSelector, headingSelector] = targets[type];
      const form = $(formSelector);
      const status = $(statusSelector);
      const result = $(resultSelector);
      const heading = $(headingSelector);
      const submit = form.querySelector('button[type="submit"]');

      clearTimeout(state.resultTimers[type]);
      result.classList.add("hidden");
      status.classList.remove("hidden");
      submit.disabled = true;
      submit.classList.add("cursor-wait", "opacity-60");
      if (isFullAssessmentFlow()) {
        status.textContent = type === "reflection" ? fullAssessmentText().finish : fullAssessmentText().advance;
        state.resultTimers[type] = setTimeout(() => {
          state.resultTimers[type] = null;
          finishFullAssessmentStep(type);
        }, 1200);
        return;
      }
      state.resultTimers[type] = setTimeout(() => {
        state.resultTimers[type] = null;
        submit.disabled = false;
        submit.classList.remove("cursor-wait", "opacity-60");
        status.classList.add("hidden");
        const detail = { assessment: "assessment", schema: "schemas", reflection: "reflection" }[type];
        if (detail) {
          window.history.pushState({ page: "results", detail }, "", `?page=results&detail=${detail}`);
          state.page = "results";
          state.resultsDetail = detail;
          applyPageLayout();
          window.scrollTo(0, 0);
          document.getElementById("results-detail-title")?.focus({ preventScroll: true });
        }
        result.classList.remove("hidden");
        if (!detail) heading.focus({ preventScroll: true });
      }, 4500);
    }

    function cancelResultReveal(type) {
      const targets = {
        assessment: ["#assessment-form", "#assessment-result-status", "#assessment-result"],
        schema: ["#schema-form", "#schema-result-status", "#schema-results"],
        reflection: ["#reflection-form", "#reflection-result-status", "#reflection-results"]
      };
      const [formSelector, statusSelector, resultSelector] = targets[type];
      clearTimeout(state.resultTimers[type]);
      state.resultTimers[type] = null;
      const form = $(formSelector);
      const status = $(statusSelector);
      const result = $(resultSelector);
      const submit = form.querySelector('button[type="submit"]');
      status.classList.add("hidden");
      result.classList.add("hidden");
      submit.disabled = false;
      submit.classList.remove("cursor-wait", "opacity-60");
    }

    function handleAssessmentSubmit(e) {
      e.preventDefault();
      if (state.resultTimers.assessment) return;
      const fd = new FormData(e.target);
      if (state.activeQuestions.some((question) => !["0", "1", "2", "3"].includes(String(fd.get(question.id))))) return;
      const raw = { stress: 0, anxiety: 0, dépression: 0, sleep: 0 };
      const counts = { stress: 0, anxiety: 0, dépression: 0, sleep: 0 };
      state.activeQuestions.forEach((q) => { raw[q.dim] += Number(fd.get(q.id)); counts[q.dim] += 1; });
      const scores = Object.fromEntries(Object.entries(raw).map(([dimension, total]) => [
        dimension,
        { score: Math.round((total / counts[dimension]) * 30) / 10, max: 9, level: severity(Math.round((total / counts[dimension]) * 30) / 10) }
      ]));

      const global = Math.round(Object.values(scores).reduce((total, item) => total + (item.score / item.max) * 100, 0) / 4);
      const mode = $("#analysis-mode").value;
      const questionIds = state.activeQuestions.map((question) => question.id);
      const date = new Date().toISOString();
      const previousSnapshot = mode === "comparative"
        ? getGuestAssessments().slice().reverse().find((item) => item.mode === "comparative" && sameQuestionSet(item.questionIds, questionIds)) || null
        : null;
      state.lastResult = { scores, mode, date, questionIds };
      localStorage.setItem("mc-combined-assessment", JSON.stringify({ scores, mode, date, questionIds }));
      saveAssessment({ id: crypto.randomUUID(), date, scores, global, mode, questionIds });
      recordAssessmentQuestionUsage(mode, state.activeQuestions);
      localStorage.removeItem(activeAssessmentDraftKey);
      updateResults(scores, mode, date, previousSnapshot, questionIds);
      renderCombinedResults();
      void saveAccountResult("assessment", { scores, mode });
      scheduleResultReveal("assessment");
    }

    async function saveAccountResult(type, payload) {
      if (!state.accountUser) return;
      const target = $(`#${type}-account-status`);
      try {
        const paths = {
          assessment: "/api/assessment-results",
          schema: "/api/schema-results",
          reflection: "/api/reflection-results"
        };
        const path = paths[type];
        await accountRequest(path, { method: "POST", body: JSON.stringify(payload) });
        target.textContent = t("account.saveSuccess");
        target.classList.remove("hidden", "text-rose-300");
        target.classList.add("text-emerald-300");
      } catch (error) {
        target.textContent = `${t("account.saveFailed")} ${error.message}`;
        target.classList.remove("hidden", "text-emerald-300");
        target.classList.add("text-rose-300");
      }
    }

