    function loadPreferences() {
      const interfaceVersion = "evora-editorial-v1";
      if (localStorage.getItem("mc-interface-version") !== interfaceVersion) {
        localStorage.setItem("mc-theme", "light");
        localStorage.setItem("mc-interface-version", interfaceVersion);
      }
      const theme = localStorage.getItem("mc-theme") || "light";
      $("#theme-select").value = theme;
      document.body.classList.toggle("theme-light", theme === "light");
    }

    function replayVisibleReveals() {
      $$(".fade-up, .scroll-reveal").forEach((el) => {
        if (!el.getClientRects().length) return;
        el.classList.add(el.classList.contains("scroll-reveal") ? "is-visible" : "show");
      });
    }

    function initReveal() {
      const selector = "main#top > section, main#top article, main#top form, main#top form fieldset, main#top section section, #primary-nav .side-icon, main#top .page-cover, #sleep-list > li, #reference-library > *, #reflection-results > *, #assessment-results > *, #schema-results > *, #combined-results article";
      const observer = "IntersectionObserver" in window ? new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          const target = entry.target;
          target.classList.add(target.classList.contains("scroll-reveal") ? "is-visible" : "show");
          observer.unobserve(target);
        });
      }, { threshold: 0.04, rootMargin: "0px 0px 100px 0px" }) : null;
      const addTarget = (el) => {
        if (!(el instanceof Element) || el.dataset.revealObserved === "true") return;
        el.dataset.revealObserved = "true";
        if (!el.classList.contains("fade-up")) el.classList.add("scroll-reveal");
        if (observer) observer.observe(el);
        else el.classList.add("is-visible", "show");
      };
      const observeNewTargets = (root) => {
        if (!(root instanceof Element)) return;
        if (root.matches(selector) || root.matches(".fade-up")) addTarget(root);
        root.querySelectorAll(`${selector}, .fade-up`).forEach(addTarget);
      };
      observeNewTargets(document.querySelector("main#top"));
      let queuedRoots = new Set();
      let scanFrame = 0;
      const mutations = new MutationObserver((records) => {
        records.forEach((record) => record.addedNodes.forEach((node) => {
          if (node instanceof Element) queuedRoots.add(node);
        }));
        if (queuedRoots.size && !scanFrame) scanFrame = requestAnimationFrame(() => {
          scanFrame = 0;
          queuedRoots.forEach(observeNewTargets);
          queuedRoots.clear();
        });
      });
      mutations.observe($("main#top"), { childList: true, subtree: true });
    }

    let scrollFrame = 0;
    let scrollableHeight = 0;
    let previousScrollProgress = -1;
    let previousScrolledState = false;
    function measureScrollRange() {
      scrollableHeight = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
    }
    function updateScrollProgress() {
      if (scrollFrame) return;
      scrollFrame = requestAnimationFrame(() => {
        scrollFrame = 0;
        const scrolled = window.scrollY > 24;
        if (scrolled !== previousScrolledState) {
          document.body.classList.toggle("has-scrolled", scrolled);
          previousScrolledState = scrolled;
        }
        const progress = scrollableHeight > 0 ? Math.min(1, Math.max(0, window.scrollY / scrollableHeight)) : 0;
        const roundedProgress = Math.round(progress * 1000) / 1000;
        if (roundedProgress !== previousScrollProgress) {
          document.documentElement.style.setProperty("--scroll-progress", roundedProgress.toFixed(3));
          previousScrollProgress = roundedProgress;
        }
      });
    }
    window.addEventListener("scroll", updateScrollProgress, { passive: true });
    window.addEventListener("resize", () => { measureScrollRange(); updateScrollProgress(); }, { passive: true });
    if ("ResizeObserver" in window) {
      const pageResizeObserver = new ResizeObserver(() => { measureScrollRange(); updateScrollProgress(); });
      pageResizeObserver.observe($("main#top"));
    }
    measureScrollRange();
    window.addEventListener("pageshow", () => {
      document.body.classList.remove("presentation-leaving");
    });
    window.addEventListener("popstate", () => renderRouteFromLocation());

    applyPageLayout();
    initEvents();
    loadPreferences();
    applyTranslations();
    restoreLatestAssessmentResult();
    renderHomeProgress();
    initReveal();
    updateScrollProgress();
    renderHistory();
    void initializeAccount();
    window.setInterval(renderDaypartNote, 60_000);
  
